import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { authAPI } from '../services/api';
import toast from 'react-hot-toast';

const ProfilePage = () => {
  const { user, logout, updateUser } = useAuth();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    name: user?.name || '',
    email: user?.email || '',
    street: user?.address?.street || '',
    city: user?.address?.city || '',
    state: user?.address?.state || '',
    pincode: user?.address?.pincode || '',
  });
  const [saving, setSaving] = useState(false);

  if (!user) { navigate('/login'); return null; }

  const handleSave = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      const res = await authAPI.updateProfile({
        name: form.name,
        email: form.email,
        address: { street: form.street, city: form.city, state: form.state, pincode: form.pincode }
      });
      updateUser(res.data.user);
      toast.success('Profile updated! ✅');
    } catch { toast.error('Failed to update profile'); }
    setSaving(false);
  };

  const handleLogout = () => {
    logout();
    navigate('/');
    toast.success('Logged out successfully');
  };

  return (
    <div className="page-fade">
      <div className="page-header"><div className="container"><h1>👤 My Profile</h1></div></div>
      <div className="container" style={{ maxWidth: 600 }}>
        {/* Profile Card */}
        <div style={{ background: 'white', borderRadius: 20, padding: 28, boxShadow: '0 4px 16px rgba(0,0,0,0.08)', marginBottom: 20 }}>
          {/* Avatar & Info */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 16, marginBottom: 28, paddingBottom: 20, borderBottom: '2px solid var(--gray-100)' }}>
            <div style={{ width: 64, height: 64, background: 'linear-gradient(135deg, var(--green), var(--green-dark))', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 28, color: 'white', fontWeight: 800, fontFamily: 'var(--font-display)', flexShrink: 0 }}>
              {user.name.charAt(0).toUpperCase()}
            </div>
            <div>
              <h2 style={{ fontFamily: 'var(--font-display)', fontSize: 22, color: 'var(--gray-800)' }}>{user.name}</h2>
              <p style={{ fontSize: 15, color: 'var(--gray-500)', marginTop: 2 }}>📱 +91 {user.phone}</p>
              {user.email && <p style={{ fontSize: 14, color: 'var(--gray-400)' }}>📧 {user.email}</p>}
            </div>
          </div>

          {/* Edit Form */}
          <form onSubmit={handleSave} style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
            <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 18, color: 'var(--gray-700)', marginBottom: 4 }}>✏️ Edit Details</h3>
            <div>
              <label style={{ fontWeight: 700, fontSize: 15, color: 'var(--gray-700)', display: 'block', marginBottom: 6 }}>Full Name</label>
              <input type="text" value={form.name} onChange={e => setForm(f => ({...f, name: e.target.value}))} style={{ fontSize: 17 }} />
            </div>
            <div>
              <label style={{ fontWeight: 700, fontSize: 15, color: 'var(--gray-700)', display: 'block', marginBottom: 6 }}>Mobile Number</label>
              <input type="text" value={`+91 ${user.phone}`} disabled style={{ background: 'var(--gray-100)', color: 'var(--gray-400)', fontSize: 16 }} />
              <p style={{ fontSize: 12, color: 'var(--gray-400)', marginTop: 4 }}>Mobile number cannot be changed</p>
            </div>
            <div>
              <label style={{ fontWeight: 700, fontSize: 15, color: 'var(--gray-700)', display: 'block', marginBottom: 6 }}>Email (Optional)</label>
              <input type="email" value={form.email} onChange={e => setForm(f => ({...f, email: e.target.value}))} placeholder="yourname@gmail.com" />
            </div>

            <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 18, color: 'var(--gray-700)', marginTop: 8, marginBottom: 4 }}>📍 Default Address</h3>
            <div>
              <label style={{ fontWeight: 700, fontSize: 15, color: 'var(--gray-700)', display: 'block', marginBottom: 6 }}>Street / House No.</label>
              <input type="text" value={form.street} onChange={e => setForm(f => ({...f, street: e.target.value}))} placeholder="Door no, Street name, Area" />
            </div>
            <div style={{ display: 'flex', gap: 12 }}>
              <div style={{ flex: 1 }}>
                <label style={{ fontWeight: 700, fontSize: 15, color: 'var(--gray-700)', display: 'block', marginBottom: 6 }}>City</label>
                <input type="text" value={form.city} onChange={e => setForm(f => ({...f, city: e.target.value}))} placeholder="City" />
              </div>
              <div style={{ flex: 1 }}>
                <label style={{ fontWeight: 700, fontSize: 15, color: 'var(--gray-700)', display: 'block', marginBottom: 6 }}>State</label>
                <input type="text" value={form.state} onChange={e => setForm(f => ({...f, state: e.target.value}))} placeholder="State" />
              </div>
            </div>
            <div>
              <label style={{ fontWeight: 700, fontSize: 15, color: 'var(--gray-700)', display: 'block', marginBottom: 6 }}>Pincode</label>
              <input type="text" value={form.pincode} onChange={e => setForm(f => ({...f, pincode: e.target.value}))} placeholder="6-digit pincode" maxLength={6} />
            </div>

            <button type="submit" disabled={saving} className="btn-primary" style={{ marginTop: 8, justifyContent: 'center', fontSize: 17, padding: '15px', opacity: saving ? 0.7 : 1 }}>
              {saving ? '⏳ Saving...' : '💾 Save Changes'}
            </button>
          </form>
        </div>

        {/* Quick Links */}
        <div style={{ background: 'white', borderRadius: 20, overflow: 'hidden', boxShadow: '0 2px 8px rgba(0,0,0,0.06)', marginBottom: 20 }}>
          {[
            { icon: '📦', label: 'My Orders', sub: 'View all your orders', link: '/orders' },
            { icon: '❤️', label: 'My Wishlist', sub: 'Products you saved', link: '/wishlist' },
          ].map(item => (
            <button key={item.link} onClick={() => navigate(item.link)}
              style={{ display: 'flex', alignItems: 'center', gap: 14, padding: '18px 20px', background: 'none', border: 'none', borderBottom: '1px solid var(--gray-100)', cursor: 'pointer', width: '100%', textAlign: 'left', transition: 'background 0.15s' }}
              onMouseEnter={e => e.currentTarget.style.background = 'var(--gray-50)'}
              onMouseLeave={e => e.currentTarget.style.background = 'none'}>
              <span style={{ fontSize: 28 }}>{item.icon}</span>
              <div style={{ flex: 1 }}>
                <div style={{ fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 16, color: 'var(--gray-800)' }}>{item.label}</div>
                <div style={{ fontSize: 13, color: 'var(--gray-400)' }}>{item.sub}</div>
              </div>
              <span style={{ color: 'var(--gray-300)', fontSize: 20 }}>›</span>
            </button>
          ))}
        </div>

        {/* Logout Button */}
        <button onClick={handleLogout}
          style={{ width: '100%', background: '#fee2e2', color: '#dc2626', border: '2px solid #fca5a5', borderRadius: 16, padding: '18px', fontSize: 18, fontWeight: 800, fontFamily: 'var(--font-display)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10, transition: 'background 0.2s', marginBottom: 40 }}
          onMouseEnter={e => e.currentTarget.style.background = '#fecaca'}
          onMouseLeave={e => e.currentTarget.style.background = '#fee2e2'}>
          🚪 Logout from My Account
        </button>
      </div>
    </div>
  );
};

export default ProfilePage;
